  const my = Math.cos(sy*0.05-t*0.7)*3 + Math.sin(sx*0.045+t*0.9)*2;
  const fx = sx+mx, fy = sy+my;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,1.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,0.9],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,1.1],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,0.8],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,1.05],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,0.95],
    [400+Math.sin(t*0.45+3)*70,140+Math.cos(t*0.65+4)*60,0.11,2.1,0.85],
    [80+Math.cos(t*0.55+2)*90,40+Math.sin(t*0.75+1)*50,0.085,1.8,1.15],
    [240+Math.sin(t*0.25)*60,220+Math.cos(t*0.45+2)*40,0.13,2.4,0.9]
  ];
  let aS=0,iS=0,glow=0;
  for(const[sX,sY,f,sp,w]of src){
    const d=Math.sqrt((fx-sX)**2+(fy-sY)**2);
    aS+=Math.sin(d*f-t*sp)*w;
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;
    glow+=Math.exp(-d*0.008)*w*(0.5+0.5*Math.sin(t*sp*0.3));
  }
  const act=aS/9,inh=iS/9;glow/=9;
  const bg1=(Math.sin(fx*0.04+fy*0.025+t*0.8)+Math.sin(fx*0.03-fy*0.04+t*1.1))/2;
  const bg2=Math.sin((fx+fy)*0.12+t*2.5)*0.2+Math.sin((fx-fy)*0.1-t*2)*0.2;
  const bg3=(Math.sin(fx*0.08-fy*0.06+t*1.8)+Math.cos(fx*0.06+fy*0.09-t*1.4))*0.15;
  const bg=bg1+bg2+bg3;
  const cx=240,cy=120,dist=Math.sqrt((fx-cx)**2+(fy-cy)**2),ang=Math.atan2(fy-cy,fx-cx);
