    const d=Math.sqrt((fx-vvx)**2+(fy-vvy)**2);
    if(d<minD){secD=minD;minD=d;}else if(d<secD)secD=d;
  }
  const voronoi=(secD-minD)*0.06;
  const reaction=Math.tanh((act-inh*0.7+bg*0.3+spiral+voronoi*0.4)*2.2);
  const cell=Math.tanh((Math.sin(fx*0.15)*Math.sin(fy*0.15)+Math.sin((fx+fy)*0.1+t)*0.5)*1.5)*0.3;
  const blend=reaction*0.6+cell*0.15+voronoi*0.1+glow*0.15,v=blend*0.5+0.5;
  const pal=[[5,10,45],[10,35,85],[15,75,115],[20,130,135],[60,170,130],[160,195,80],[220,190,55],[230,140,60],[215,95,65],[185,55,70],[140,35,75],[85,25,65],[40,15,55],[5,10,45]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=0.8+Math.sin(reaction*Math.PI)*0.2;
  const boost=lum*(Math.abs(reaction)>0.7?1.12:1.0)*(1.0+glow*0.3);
  return[
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*boost)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*boost)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*boost)|0
  ];
}
